local runId = { farm = 0, rebirth = 0, sell = 0, train = 0, egg = 0, roll = 0 }

local function Loop(key, enabled, getDelay, fn)
    runId[key] += 1
    if not enabled then return end
    local id = runId[key]
    task.spawn(function()
        while runId[key] == id do
            local ok, err = pcall(fn)
            if not ok then warn("[" .. key .. "] " .. tostring(err)) end
            task.wait(getDelay())
        end
    end)
end


local LP = game:GetService("Players").LocalPlayer
local function Stat(name)
    local ls = LP:FindFirstChild("leaderstats")
    local s = ls and ls:FindFirstChild(name)
    return s and tonumber(s.Value) or 0
end

local function StatRaw(name)
    local ls = LP:FindFirstChild("leaderstats")
    local s = ls and ls:FindFirstChild(name)
    return s and s.Value
end

local function HRP()
    local c = LP.Character
    return c and c:FindFirstChild("HumanoidRootPart")
end

-- spot terdekat dari posisi player untuk tree tertentu
local function NearestSpot(tree)
    local hrp = HRP()
    if not hrp then return end
    local bestPos, bestDist, bestWorld
    for world, list in pairs(TREES) do
        local pos = list[tree]
        if pos then
            local d = (hrp.Position - pos).Magnitude
            if not bestDist or d < bestDist then
                bestPos, bestDist, bestWorld = pos, d, world
            end
        end
    end
    return bestPos, bestWorld
end

local function GoTo(pos)
    local hrp = HRP()
    if hrp and pos then hrp.CFrame = CFrame.new(pos + Vector3.new(0, 3, 0)) end
end

-- teleport ke tree, hit 5x, cek Strength berubah = tree terbuka
local function Probe(tree)
    local pos = NearestSpot(tree)
    if not pos then return false end
    GoTo(pos)
    task.wait(0.3)
    local remote = RS:WaitForChild("TrainHit")
    local before = StatRaw("Strength")
    for _ = 1, 5 do
        remote:FireServer("TrainTree" .. tree)
        task.wait(0.05)
    end
    task.wait(0.5)
    return StatRaw("Strength") ~= before
end

local TrainBest, TrainBestReb = 0, nil

-- tentukan tree tertinggi yang terbuka; hasil di-cache per jumlah Rebirths
local function DetectTree(id)
    local forced = tonumber(TRAIN_FORCE)
    if forced then return forced end

    local reb = Stat("Rebirths")
    if TrainBest > 0 and TrainBestReb == reb then return TrainBest end

    Probing = true
    if TrainBest == 0 then
        for tr = TRAIN_MAX_TREE, 1, -1 do
            if runId.train ~= id then break end
            local ok, res = pcall(Probe, tr)
            if ok and res then TrainBest = tr break end
        end
        if TrainBest == 0 and runId.train == id then
            TrainBest = 1
            N("Auto Train", "Tidak ada yang terdeteksi, pakai TrainTree1", "#FFA500", 4)
        end
    else
        while runId.train == id and TrainBest < TRAIN_MAX_TREE do
            local ok, res = pcall(Probe, TrainBest + 1)
            if ok and res then TrainBest += 1 else break end
        end
    end
    Probing = false
    TrainBestReb = reb
    return TrainBest
end

