local tog_train = P_Main:Toggle({
    Title        = "Auto Train",
    Desc         = "Cek tree terbuka (per Rebirth), teleport ke tree terdekat, lalu train",
    Value        = false,
    id           = "auto_train",
    CornerRadius = UDim.new(1, 0),
    Callback     = function(v)
        runId.train += 1
        if not v then
            Probing = false
            CurrentTree, CurrentWorld = nil, nil
            N("Auto Train", "OFF", "#DC3232")
            return
        end
        local id = runId.train
        task.spawn(function()
            local spot
            while runId.train == id do
                local tree = DetectTree(id)
                if runId.train ~= id then return end

                -- kunci spot saat tree berubah supaya tidak pindah-pindah
                if tree ~= CurrentTree or not spot then
                    local pos, world = NearestSpot(tree)
                    if pos then
                        spot, CurrentTree, CurrentWorld = pos, tree, world
                        N("Auto Train", "TrainTree" .. tree .. " (" .. world .. ")", "#50C864")
                    end
                end

                local hrp = HRP()
                if spot and hrp and (hrp.Position - spot).Magnitude > 12 then
                    GoTo(spot)
                    task.wait(0.2)
                end

                if CurrentTree then
                    pcall(function()
                        RS:WaitForChild("TrainHit"):FireServer("TrainTree" .. CurrentTree)
                    end)
                end
                task.wait(TRAIN_DELAY)
            end
        end)
        N("Auto Train", "ON - mengecek tree...", "#50C864")
    end,
})

